content.text:
switch (state) {
    case DATA_STATE:
        if (c == '<') {
            state = TAG_OPEN_STATE;
        }
        else if (c == '&') {
            state = CHARACTER_REFERENCE_STATE;
        }
        else {
            emitCharacter(c);
        }
        break;

    case CHARACTER_REFERENCE_STATE:
        char decoded = decodeEntity(); // &lt; -> '<'

        emitCharacter(decoded);
        state = DATA_STATE;
        break;
}
